actions.script:
import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
def ds = java.sql.Timestamp.valueOf(fromD + ' 00:00:00')
def de = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def ef = ec.entity.find("zenith.erp.pos.PosTransactionView")
    .condition("entryDate","greater-equals",ds).condition("entryDate","less-equals",de).orderBy("-entryDate")
if (statusId) ef.condition("statusId", statusId)
if (_org) ef.condition("organizationPartyId", _org)
def bills = ef.list()
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) bills = bills.findAll { ((it.transactionNumber ?: '').toString().toLowerCase().contains(stx) || (it.customerName ?: '').toLowerCase().contains(stx)) }
def canon = { m -> def k=(m ?: '').toString().trim(); def lk=k.toLowerCase();
    if(lk=='cash')return 'Cash'; if(lk=='upi')return 'UPI'; if(lk=='card')return 'Card';
    if(lk=='netbanking'||lk=='net banking')return 'Net Banking'; if(lk=='wallet')return 'Wallet'; if(lk=='credit')return 'Credit'; return k }
def billIds = bills.collect { it.transactionId }
def payAgg = [:]
if (billIds) ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId","in",billIds).list().each { p ->
    def mm = payAgg.get(p.transactionId, [:]); def k = canon(p.paymentMethod); mm[k] = (mm[k] ?: 0.0G) + ((p.amount ?: 0) as BigDecimal) }
def payType = { b -> (b.isCredit == 'Y') ? 'Credit' : (payAgg[b.transactionId] ? payAgg[b.transactionId].entrySet().max{ it.value }.key : '') }
def slMap = [PtCompleted:'Completed', PtVoided:'Cancelled', PtHeld:'Pending', PtCreated:'Pending']
def statusOf = { b -> (b.isCredit == 'Y') ? 'Credit' : (slMap[b.statusId] ?: b.statusId) }
def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def num = { v -> String.format("%.2f", (v ?: 0.0) as double) }
def dt = { v -> v == null ? "" : ec.l10n.format(v, 'dd-MM-yyyy HH:mm') }
StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - Bill Wise Report\n")
csv.append("Period: ${fromD} to ${thruD}  |  Generated: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
csv.append("Bill No,Date,Terminal,Customer,Subtotal,Discount,Tax,Net Amount,Payment Type,Status\n")
bills.each { b ->
    csv.append("${esc(b.transactionNumber ?: b.transactionId)},${dt(b.entryDate)},${esc(b.terminalName)},${esc(b.customerName ?: 'Walk-in Customer')},${num(b.subtotal)},${num(b.discountTotal)},${num(b.totalTaxAmount)},${num(b.payableAmount)},${esc(payType(b))},${esc(statusOf(b))}\n")
}
ec.web.sendTextResponse(csv.toString(), "text/csv", "Bill_Wise_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv")

def zinr = context.zinr
// Payment type per bill: dominant PosPayment method (batch, one query), or "Credit" for pay-later bills
def canon = { m -> def k=(m ?: '').toString().trim(); def lk=k.toLowerCase();
    if(lk=='cash')return 'Cash'; if(lk=='upi')return 'UPI'; if(lk=='card')return 'Card';
    if(lk=='netbanking'||lk=='net banking')return 'Net Banking'; if(lk=='wallet')return 'Wallet'; if(lk=='credit')return 'Credit'; return k }
def billIds = billList.collect { it.transactionId }
def payAgg = [:]
if (billIds) ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId","in",billIds).list().each { p ->
    def mm = payAgg.get(p.transactionId, [:]); def k = canon(p.paymentMethod); mm[k] = (mm[k] ?: 0.0G) + ((p.amount ?: 0) as BigDecimal) }
def payTypeByTxn = [:]
payAgg.each { tid, mm -> payTypeByTxn[tid] = mm.entrySet().max{ it.value }.key }
context.payTypeByTxn = payTypeByTxn

// 5 stat cards
def completed = billList.findAll { it.statusId == 'PtCompleted' }
def salesBills = completed.findAll { it.isCredit != 'Y' }
def creditBills = billList.findAll { it.isCredit == 'Y' }
def pendingBills = billList.findAll { (((it.payableAmount ?: 0) as BigDecimal) - ((it.paidAmount ?: 0) as BigDecimal)) > 0 }
def totalSales = salesBills.inject(0.0G) { a, it -> a + ((it.payableAmount ?: 0) as BigDecimal) }
def totalDiscount = completed.inject(0.0G) { a, it -> a + ((it.discountTotal ?: 0) as BigDecimal) }
def pendingAmt = pendingBills.inject(0.0G) { a, it -> a + (((it.payableAmount ?: 0) as BigDecimal) - ((it.paidAmount ?: 0) as BigDecimal)) }
def creditAmt = creditBills.inject(0.0G) { a, it -> a + ((it.payableAmount ?: 0) as BigDecimal) }
def avgDiscPct = totalSales > 0 ? (totalDiscount * 100 / totalSales) : 0.0G

totalSalesStr = '₹ ' + zinr.inr(ec.l10n.format(totalSales, '#,##0.00'))
salesBillsStr = salesBills.size() + ' Bills'
totalBillsCount = billList.size()
terminalsStr = (billList.collect { it.terminalName }.findAll { it }.unique().size()) + ' Terminals'
totalDiscountStr = '₹ ' + zinr.inr(ec.l10n.format(totalDiscount, '#,##0.00'))
avgDiscStr = 'Avg. Discount ' + ec.l10n.format(avgDiscPct, '#0.00') + '%'
pendingAmtStr = '₹ ' + zinr.inr(ec.l10n.format(pendingAmt, '#,##0.00'))
pendingBillsStr = pendingBills.size() + ' Bills'
creditAmtStr = '₹ ' + zinr.inr(ec.l10n.format(creditAmt, '#,##0.00'))
creditBillsStr = creditBills.size() + ' Bills'

row-actions.script:
billNo = bill.transactionNumber ?: bill.transactionId
def pt = (bill.isCredit == 'Y') ? 'Credit' : (payTypeByTxn[bill.transactionId] ?: '—')
paymentType = pt
// mockup: Cash/Card/Credit = violet, UPI = blue
payColor = [Cash:'primary', Card:'primary', Credit:'primary', UPI:'info'][pt] ?: 'grey'
def scMap = [PtCompleted:'success', PtVoided:'grey', PtHeld:'warning', PtCreated:'warning']
def slMap = [PtCompleted:'Completed', PtVoided:'Cancelled', PtHeld:'Pending', PtCreated:'Pending']
if (bill.isCredit == 'Y') { statusText = 'Credit'; statusColor = 'primary' }
else { statusColor = scMap[bill.statusId] ?: 'grey'; statusText = slMap[bill.statusId] ?: (bill.statusId ?: '—') }
customerDisp = bill.customerName ?: 'Walk-in Customer'
